from hran_radio.radio_classes.radio_5_1_base import Radio5_1Base
from hran_radio.radio_commands.rmod_51_commands import get_map_cmd_for, get_trx_power_command, get_trx_carrier_command
from hran_radio.radio_output_parser.five_one_parser import RadioOutputParser
from hran_radio.exceptions import NotImplementedYet
from collections import defaultdict


class Radio5_1DualNAHKADualBand(Radio5_1Base):
    """
In dictionary self.physical_antenna_map key is path from frmon map and value is physical RM antenna pipe
    """

    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(Radio5_1DualNAHKADualBand, self).__init__(radio_ip, sm_ip, msm_ip)
        self.parser = RadioOutputParser()
        self.first_nahka_ip = radio_ip
        self.second_nahka_ip = "192.168.101.3"
        self.physical_antenna_map = {
            "ant1": "ant1",
            "ant2": "ant1",
            "ant3": "ant2",
            "ant4": "ant2",
            "ant5": "ant3",
            "ant6": "ant3",
            "ant7": "ant4",
            "ant8": "ant4",
        }

    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
        raw_tx_maps = self._run_map_commands_on_both_nahka(get_map_cmd_for, "tx")
        tx_maps = self._parse_both_maps(self.parser.parse_trx_map, raw_tx_maps)
        raw_powers = self._run_read_commands_on_both_nahka(
            get_trx_power_command, tx_maps
        )
        return self.parser.parse_tx_power(raw_powers[0] + "\n" + raw_powers[1])

    def all_rx_power(self):
        """
        Return all rx power in format {tx: power}.

        :return: rx power
        :rtype: dict
        """
        raw_rx_maps = self._run_map_commands_on_both_nahka(get_map_cmd_for, "rx")
        rx_maps = self._parse_both_maps(self.parser.parse_trx_map, raw_rx_maps)
        raw_powers = self._run_read_commands_on_both_nahka(
            get_trx_power_command, rx_maps
        )
        return self.parser.parse_rx_power(raw_powers[0] + "\n" + raw_powers[1])

    def front_end_gain(self, antenna_number):
        """
        Return front end gain for rx.

        :return: front end gain
        :rtype: float
        """
        raise NotImplementedYet

    def tx_carrier_data(self):
        """
        Return tx carrier data.

        :return: tx carrier data
        :rtype: dict
        """
        raw_tx_maps = self._run_map_commands_on_both_nahka(get_map_cmd_for, "tx")
        tx_maps = self._parse_both_maps(self.parser.parse_trx_map, raw_tx_maps)
        raw_tx_data = self._run_read_commands_on_both_nahka(
            get_trx_carrier_command, tx_maps
        )
        tx_data = self.parser.parse_trx_carrier(raw_tx_data[0] + "\n" + raw_tx_data[1])
        parsed_tx_data = defaultdict(dict)
        for key, value in tx_data.items():
            temp = parsed_tx_data[self.physical_antenna_map[key]]
            temp.update(value)
            parsed_tx_data[self.physical_antenna_map[key]] = temp
        return parsed_tx_data

    def rx_carrier_data(self):
        """
        Return rx carrier data.

        :return: rx carrier data
        :rtype: dict
        """
        raw_rx_maps = self._run_map_commands_on_both_nahka(get_map_cmd_for, "rx")
        rx_maps = self._parse_both_maps(self.parser.parse_trx_map, raw_rx_maps)
        raw_rx_data = self._run_read_commands_on_both_nahka(
            get_trx_carrier_command, rx_maps
        )
        rx_data = self.parser.parse_trx_carrier(raw_rx_data[0] + "\n" + raw_rx_data[1])
        parsed_rx_data = defaultdict(dict)
        for key, value in rx_data.items():
            temp = parsed_rx_data[self.physical_antenna_map[key]]
            temp.update(value)
            parsed_rx_data[self.physical_antenna_map[key]] = temp
        return parsed_rx_data

    def _parse_both_maps(self, parser_func, raw_maps):
        """
        Parse trx maps

        :param parser_func: parser func
        :param raw_maps: raw maps tuple
        :return: tuple
        """
        _first = parser_func(raw_maps[0])
        _second = parser_func(raw_maps[1])
        return _first, _second

    def _run_map_commands_on_both_nahka(self, map_func, trx):
        """
        Run map commands on both nahka

        :param map_func: function create map
        :param trx: tx or rx str()
        :return: tuple(first_raw_map, second_raw_map)
        """
        _first = self._execute_radio_command(
            map_func(trx, first_ant_num=1, last_ant_num=4), self.first_nahka_ip
        )
        _second = self._execute_radio_command(
            map_func(trx, first_ant_num=5, last_ant_num=8), self.second_nahka_ip
        )
        return _first, _second

    def _run_read_commands_on_both_nahka(self, get_cmd_func, map_trx):
        """
        Run read command on both nahka

        :param get_cmd_func: function create read command
        :param map_trx: mapped trx, tuple
        :return: tuple
        """
        _first = self._execute_radio_command(
            get_cmd_func(map_trx[0]), self.first_nahka_ip
        )
        _second = self._execute_radio_command(
            get_cmd_func(map_trx[1]), self.second_nahka_ip
        )
        return _first, _second

    def _execute_radio_command(self, command, ip_nahka):
        """
        Set nahka ip and execute command

        :param command: cmd, str
        :param ip_nahka: ip, str
        :return: cmd output
        """
        self.radio_connection.set_frmon_ip(ip_nahka)
        return self.run_radio_command(command)
